import Foundation

/// A task, as the API returns it. `notes` is `description` on the wire.
struct TaskItem: Codable, Identifiable, Hashable, Sendable {
    /// Lowercase UUID, generated by the client.
    var id: String
    var date: DayKey
    /// 1…500 characters after trimming.
    var title: String
    /// Up to 5000 characters.
    var notes: String
    var done: Bool
    /// ISO 8601 timestamps; creation order sorts by `createdAt` as a string, as on the web.
    var createdAt: String
    var updatedAt: String

    enum CodingKeys: String, CodingKey {
        case id, date, title, notes = "description", done, createdAt, updatedAt
    }

    static let titleMax = 500
    static let notesMax = 5000

    static func newID() -> String { UUID().uuidString.lowercased() }

    /// Now, in the same format the server uses (`2026-10-23T09:41:00.000Z`).
    static func timestamp(_ date: Date = .now) -> String {
        Date.ISO8601FormatStyle(includingFractionalSeconds: true).format(date)
    }
}

/// The editable fields; nil means unchanged. Mirrors `TaskPatch` on the server.
struct TaskPatch: Codable, Hashable, Sendable {
    var title: String?
    var notes: String?
    var date: DayKey?
    var done: Bool?

    enum CodingKeys: String, CodingKey {
        case title, notes = "description", date, done
    }

    var isEmpty: Bool { title == nil && notes == nil && date == nil && done == nil }

    /// `other`'s fields win.
    func merged(with other: TaskPatch) -> TaskPatch {
        TaskPatch(title: other.title ?? title, notes: other.notes ?? notes, date: other.date ?? date, done: other.done ?? done)
    }

    func applied(to task: TaskItem) -> TaskItem {
        var t = task
        if let title { t.title = title }
        if let notes { t.notes = notes }
        if let date { t.date = date }
        if let done { t.done = done }
        return t
    }
}
